    verdict: decideVerdict(coverage, coverageThreshold),
    reason: decideVerdict(coverage, coverageThreshold) === VERDICT.REJECT ? REASON_DEFECT : REASON_NO_DEFECT,
    coverage,
    coverageThreshold,
    boxCount: detections.length,
    detections,
    ...prompt
  };
